import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`ja/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to “トラブルシューティング”">​</a></h1><p>このページでは、よくある問題とその解決方法をまとめています。</p><h2 id="アプリが起動しない、起動直後にクラッシュする" tabindex="-1">アプリが起動しない、起動直後にクラッシュする <a class="header-anchor" href="#アプリが起動しない、起動直後にクラッシュする" aria-label="Permalink to “アプリが起動しない、起動直後にクラッシュする”">​</a></h2><p>症状：Sudoku が開かない、すぐにクラッシュする、予期しないエラーが表示される。</p><p>お試しいただきたい手順：</p><ol><li>デバイスが最低要件（iOS/iPadOS 16 以降、macOS 15 以降）を満たしていることを確認します。</li><li>アプリを強制終了してから再起動します。</li><li>デバイスを再起動します。</li><li>App Store からアプリを再インストールします。</li><li>問題が解決しない場合は、詳細を添えてプロジェクトリポジトリで issue を作成してください。</li></ol><h2 id="動作が重い" tabindex="-1">動作が重い <a class="header-anchor" href="#動作が重い" aria-label="Permalink to “動作が重い”">​</a></h2><p>ゲームの動作が遅い、カクつく場合：</p><ol><li>負荷の高い他のアプリを終了します。</li><li>Mac では、アクティビティモニタで CPU 使用率が高くないか確認します。</li><li>古いデバイスでは、より簡単な難易度（やさしいまたはふつう）を試してください。</li></ol><h2 id="icloud-の同期が機能しない" tabindex="-1">iCloud の同期が機能しない <a class="header-anchor" href="#icloud-の同期が機能しない" aria-label="Permalink to “iCloud の同期が機能しない”">​</a></h2><p>進行状況がデバイス間で同期されない場合：</p><ol><li>すべてのデバイスで同じ Apple ID にサインインしていることを確認します。</li><li>システム設定（Mac）または設定（iOS/iPadOS）で iCloud Drive が有効になっていることを確認します。</li><li>インターネット接続が有効であることを確認します。</li><li>設定 → [あなたの名前] → iCloud → iCloud を使用する App で、Sudoku の iCloud を一度オフにしてから再度オンにします。</li><li>すべてのデバイスを再起動して、もう一度お試しください。</li></ol><h2 id="game-center-に接続できない" tabindex="-1">Game Center に接続できない <a class="header-anchor" href="#game-center-に接続できない" aria-label="Permalink to “Game Center に接続できない”">​</a></h2><p>Game Center の実績やリーダーボードが更新されない場合：</p><ol><li>Game Center にサインインしていることを確認します（iOS では設定 → Game Center、Mac ではシステム設定）。</li><li>インターネット接続を確認します。</li><li>Game Center からサインアウトし、再度サインインします。</li></ol><h2 id="ログを確認する" tabindex="-1">ログを確認する <a class="header-anchor" href="#ログを確認する" aria-label="Permalink to “ログを確認する”">​</a></h2><p>クラッシュの原因を調べるには、アプリケーションログが役立ちます。Mac のサンドボックス（App Store）版では、次を確認してください：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>iOS/iPadOS では、デバイスを Mac に接続し、Console.app で「Sudoku」で絞り込んでログを表示します。</p><h2 id="アプリをリセットする" tabindex="-1">アプリをリセットする <a class="header-anchor" href="#アプリをリセットする" aria-label="Permalink to “アプリをリセットする”">​</a></h2><p>設定を初期化し、ローカルデータを消去する方法（Mac）：</p><ol><li>Sudoku を終了します</li><li>コンテナを削除します（注意 — 設定、統計、ゲームのセーブデータがすべて削除されます）：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>Sudoku を再度開き、設定し直します。</li></ol><p>iPhone/iPad では、アプリを削除して再インストールするとすべてのデータがリセットされます。</p><p><strong>注意</strong>：iCloud 同期を使用している場合、1 台のデバイスでリセットしても、再起動後に iCloud からデータが再ダウンロードされることがあります。すべてのデバイスで完全にリセットするには、各デバイスでリセットが必要になる場合があります。</p><h2 id="問題を報告する" tabindex="-1">問題を報告する <a class="header-anchor" href="#問題を報告する" aria-label="Permalink to “問題を報告する”">​</a></h2><p>issue を作成する際は、次の情報を含めてください：</p><ul><li>デバイスの種類（iPhone、iPad、Mac）</li><li>OS のバージョン（設定 → 一般 → 情報）</li><li>Sudoku のバージョン（設定 → 概要）</li><li>問題の再現手順</li><li>可能であればログやスクリーンショット</li></ul><p>これらの情報があると、メンテナーが問題を特定し、より早く修正できます。</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};